    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 2px solid #ffffff;
      outline-offset: 3px;
    }

    .page {
      width: min(100%, 920px);
    }

    .shell {
      background: rgba(18, 26, 49, 0.92);
      border: 1px solid rgba(92, 113, 168, 0.3);
      border-radius: 28px;
      box-shadow: var(--shadow);
      overflow: hidden;
      backdrop-filter: blur(16px);
    }

    .hero {
      display: grid;
      gap: 28px;
      grid-template-columns: minmax(0, 1.4fr) minmax(280px, 0.85fr);
      padding: 28px;
    }

    .image-panel {
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02));
      border: 1px solid rgba(125, 145, 196, 0.22);
      border-radius: 24px;
      padding: 18px;
    }

    .preview-image {
      width: 100%;
      display: block;
      border-radius: 18px;
      border: 1px solid rgba(164, 180, 227, 0.16);
      background: #0a1020;
      aspect-ratio: 4 / 3;
      object-fit: cover;
    }

    .controls {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 12px;
      margin-top: 18px;
      flex-wrap: wrap;
    }

    .meta {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .trigger {
      background: linear-gradient(180deg, var(--danger), var(--danger-strong));
      color: #fff;
      min-width: 124px;
      box-shadow: 0 10px 24px rgba(255, 77, 103, 0.28);
    }

    .details {
      display: grid;
      align-content: center;
      gap: 14px;
    }

    .eyebrow {
      color: #97abf4;
      text-transform: uppercase;
      letter-spacing: 0.12em;
      font-size: 0.78rem;
      font-weight: 700;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 3.2rem);
      line-height: 1.05;
    }

    p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .tag-row {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
    }

    .tag {
      padding: 0.5rem 0.8rem;
      border-radius: 999px;
      background: rgba(124, 156, 255, 0.12);
      border: 1px solid rgba(124, 156, 255, 0.2);
      color: #dce5ff;
      font-size: 0.92rem;
    }

    dialog {
      width: min(100%, 420px);
      padding: 0;
      border: 1px solid rgba(145, 161, 208, 0.2);
      border-radius: 24px;
      background: linear-gradient(180deg, #131c35 0%, #0f1529 100%);
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(2, 6, 17, 0.72);
      backdrop-filter: blur(6px);
    }

    .dialog-content {
      padding: 24px;
    }

    .dialog-icon {
      width: 52px;
      height: 52px;
      display: inline-grid;
      place-items: center;
      border-radius: 16px;
      background: rgba(255, 107, 129, 0.14);
      color: #ff94a3;
      margin-bottom: 18px;
      font-size: 1.3rem;
      font-weight: 700;
    }

    .dialog-title {
      margin: 0 0 10px;
      font-size: 1.45rem;
    }

    .dialog-copy {
      margin-bottom: 24px;
    }

    .dialog-actions {
      display: flex;
      gap: 12px;
      justify-content: flex-end;
      flex-wrap: wrap;
    }

    .secondary {
      background: transparent;
      color: var(--text);
      border: 1px solid rgba(168, 182, 222, 0.22);
    }

    .danger {
      background: linear-gradient(180deg, var(--danger), var(--danger-strong));
      color: #fff;
    }

    .status {
      min-height: 1.5rem;
      margin-top: 12px;
      color: #dfe7ff;
      font-weight: 600;
    }

    .status[data-state="deleted"] {
      color: #ffb3bf;
    }

    @media (max-width: 760px) {
      .hero {
        grid-template-columns: 1fr;
      }
    }

    @media (forced-colors: active) {
      body {
        background: Canvas;
        color: CanvasText;
