        <defs>
          <linearGradient id="sky" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stop-color="#1b2850" />
            <stop offset="55%" stop-color="#34508d" />
            <stop offset="100%" stop-color="#f08d7f" />
          </linearGradient>
          <linearGradient id="water" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stop-color="#1f4a7f" />
            <stop offset="100%" stop-color="#09192f" />
          </linearGradient>
        </defs>
        <rect width="960" height="720" fill="url(#sky)" />
        <circle cx="736" cy="150" r="58" fill="#ffd6a5" opacity="0.95" />
        <rect y="430" width="960" height="290" fill="url(#water)" />
        <path d="M0 450 C160 380, 260 520, 400 445 S720 520, 960 430 L960 720 L0 720 Z" fill="#0f2547" />
        <path d="M560 290 L690 220 L760 430 L592 470 Z" fill="#1d2a4f" />
        <path d="M140 330 L330 250 L410 530 L140 540 Z" fill="#17223f" />
        <path d="M425 368 L600 300 L662 520 L452 570 Z" fill="#22335d" opacity="0.8" />
      </svg>
    `);

    const ImagePreview = () => `
      <section class="image-panel" aria-labelledby="image-title">
        <img
          class="preview-image"
          src="${previewSrc}"
          alt="Ocean cliffs and water at dusk"
          id="preview-image"
        />
        <div class="controls">
          <div class="meta">
            <strong id="image-title">Ocean Cliffs</strong><br>
            Added to your library • 5.2 MB
          </div>
          <button type="button" class="trigger" id="open-dialog">
            Delete image
          </button>
        </div>
        <div class="status" id="status-message" aria-live="polite" tabindex="-1"></div>
      </section>
    `;

    const DetailsPanel = () => `
      <section class="details" aria-label="Image details">
        <div class="eyebrow">Preview</div>
        <h1>Review your saved image before removing it.</h1>
        <p>
          Open the confirmation dialog to remove this image from your library.
          The modal starts closed and only appears after selecting the delete action.
        </p>
        <div class="tag-row" aria-label="Image tags">
          <span class="tag">Landscape</span>
          <span class="tag">Dark theme</span>
          <span class="tag">Library item</span>
        </div>
      </section>
    `;

    const ConfirmDeleteDialog = () => `
      <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-copy">
        <div class="dialog-content">
          <div class="dialog-icon" aria-hidden="true">!</div>
          <h2 class="dialog-title" id="dialog-title">Delete this image?</h2>
          <p class="dialog-copy" id="dialog-copy">
