          </p>
          <div class="dialog-actions">
            <button type="button" class="secondary" id="cancel-delete">Cancel</button>
            <button type="button" class="danger" id="confirm-delete">Delete image</button>
          </div>
        </div>
      </dialog>
    `;

    const App = () => `
      <main class="page">
        <div class="shell">
          <div class="hero">
            ${ImagePreview()}
            ${DetailsPanel()}
          </div>
        </div>
        ${ConfirmDeleteDialog()}
      </main>
    `;

    document.getElementById("app").innerHTML = App();

    const dialog = document.getElementById("delete-dialog");
    const openButton = document.getElementById("open-dialog");
    const cancelButton = document.getElementById("cancel-delete");
    const confirmButton = document.getElementById("confirm-delete");
    const previewImage = document.getElementById("preview-image");
    const statusMessage = document.getElementById("status-message");
    let lastFocusedElement = null;

    openButton.addEventListener("click", () => {
      lastFocusedElement = document.activeElement;
      dialog.showModal();
      cancelButton.focus();
    });

    const closeDialog = (restoreTarget = lastFocusedElement) => {
      dialog.close();
      if (restoreTarget instanceof HTMLElement) {
        restoreTarget.focus();
      }
    };

    cancelButton.addEventListener("click", closeDialog);

    confirmButton.addEventListener("click", () => {
      previewImage.style.opacity = "0.28";
      previewImage.alt = "Deleted image preview";
      openButton.disabled = true;
      openButton.textContent = "Deleted";
      statusMessage.textContent = "Image deleted from your library.";
      statusMessage.dataset.state = "deleted";
      closeDialog(statusMessage);
    });
  </script>
</body>
